class InstallError(RuntimeError):
    pass


def run(
    args: list[str],
    *,
    cwd: Path,
    check: bool = True,
    capture: bool = True,
    env: dict[str, str] | None = None,
) -> subprocess.CompletedProcess[str]:
    print("$ " + " ".join(args))
    completed = subprocess.run(
        args,
        cwd=cwd,
        check=False,
        text=True,
        capture_output=capture,
        env=env,
    )
    if check and completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or "").strip()
        raise InstallError(
            f"Komut başarısız: {' '.join(args)}\n{detail}"
        )
    return completed


def locate_repo() -> Path:
    candidates = [Path.cwd(), Path("/workspaces/BilgiRotasi")]
    for candidate in candidates:
        if not candidate.exists():
            continue
        result = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            cwd=candidate,
            check=False,
            text=True,
            capture_output=True,
        )
        if result.returncode == 0:
            return Path(result.stdout.strip())
    raise InstallError(
        "BilgiRotasi Git deposu bulunamadı. "
        "Dosyayı /workspaces/BilgiRotasi içinde çalıştır."
    )


def sha256(path: Path) -> str | None:
    if not path.exists():
        return None
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def replace_once(
    text: str,
    old: str,
    new: str,
    *,
    label: str,
) -> str:
    count = text.count(old)
    if count != 1:
        raise InstallError(
            f"{label} için beklenen bölüm bulunamadı. "
            f"Eşleşme sayısı: {count}"
        )
    return text.replace(old, new, 1)


def regex_once(
    text: str,
    pattern: str,
    replacement: str,
    *,
    label: str,
    flags: int = 0,
) -> str:
    updated, count = re.subn(
        pattern,
        replacement,
        text,
        count=1,
        flags=flags,
    )
    if count != 1:
        raise InstallError(
            f"{label} için beklenen bölüm bulunamadı. "
            f"Eşleşme sayısı: {count}"
        )
    return updated


def png_info(data: bytes) -> tuple[int, int, int]:
    if not data.startswith(b"\x89PNG\r\n\x1a\n"):
        raise InstallError("Piyon görsellerinden biri geçerli PNG değil.")
    if data[12:16] != b"IHDR":
        raise InstallError("PNG IHDR bölümü okunamadı.")
    width, height, _, color_type, _, _, _ = struct.unpack(
        ">IIBBBBB",
        data[16:29],
    )
    return width, height, color_type


def verify_asset_payloads() -> dict[Path, bytes]:
    decoded: dict[Path, bytes] = {}
    for relative, payload in ASSETS.items():
        try:
            data = base64.b64decode(payload, validate=True)
        except Exception as error:
            raise InstallError(
                f"Görsel paketi çözülemedi: {relative} / {error}"
            ) from error
        width, height, color_type = png_info(data)
        if (width, height) != (640, 640):
            raise InstallError(
                f"Beklenmeyen piyon ölçüsü: {relative} "
                f"({width}x{height})"
            )
        if color_type not in {4, 6}:
            raise InstallError(
                f"Şeffaf PNG bekleniyordu: {relative}"
            )
        decoded[Path(relative)] = data
    return decoded


def backup_targets(repo: Path, backup: Path) -> dict[Path, bool]:
    existed: dict[Path, bool] = {}
    for relative in INTENDED_TARGETS:
        source = repo / relative
        existed[relative] = source.exists()
        if source.exists():
            destination = backup / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, destination)
    return existed


def restore_targets(
    repo: Path,
    backup: Path,
    existed: dict[Path, bool],
) -> None:
    for relative in INTENDED_TARGETS:
        destination = repo / relative
        if existed.get(relative, False):
            source = backup / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, destination)
        elif destination.exists():
            destination.unlink()


