def patch_versions(
    contents: dict[Path, str],
) -> dict[Path, str]:
    contents[PUBSPEC] = replace_once(
        contents[PUBSPEC],
        "version: 1.48.1+65",
        "version: 1.48.2+66",
        label="pubspec sürümü",
    )

    build = contents[BUILD_INFO]
    build = replace_once(
        build,
        "  static const String versionName = '1.48.1';",
        "  static const String versionName = '1.48.2';",
        label="uygulama sürüm adı",
    )
    build = replace_once(
        build,
        "  static const int buildNumber = 65;",
        "  static const int buildNumber = 66;",
        label="uygulama yapı numarası",
    )
    contents[BUILD_INFO] = build

    rc = contents[RC_TEST]
    rc = rc.replace("'1.48.1'", "'1.48.2'")
    rc = replace_once(
        rc,
        "expect(AppBuildInfo.buildNumber, 65);",
        "expect(AppBuildInfo.buildNumber, 66);",
        label="RC2 test yapı numarası",
    )
    rc = rc.replace("'1.48.1+65'", "'1.48.2+66'")
    rc = rc.replace(
        "'Sürüm 1.48.1+65 • RC2'",
        "'Sürüm 1.48.2+66 • RC2'",
    )
    rc = replace_once(
        rc,
        "      expect(PawnCatalog.all.length, 16);",
        "      expect(PawnCatalog.all.length, 17);",
        label="RC2 piyon katalog sayısı",
    )
    contents[RC_TEST] = rc

    contents[QUALITY] = replace_once(
        contents[QUALITY],
        'EXPECTED_VERSION = "1.48.1+65"',
        'EXPECTED_VERSION = "1.48.2+66"',
        label="kalite kapısı sürümü",
    )

    workflow = contents[WORKFLOW]
    old_plus_count = workflow.count("1.48.1+65")
    old_dash_count = workflow.count("1.48.1-65")
    if old_plus_count < 1 or old_dash_count < 1:
        raise InstallError(
            "Workflow sürüm işaretleri bulunamadı."
        )
    workflow = workflow.replace("1.48.1+65", "1.48.2+66")
    workflow = workflow.replace("1.48.1-65", "1.48.2-66")
    contents[WORKFLOW] = workflow

    checklist = contents[CHECKLIST]
    if "1.47.1+63" not in checklist:
        raise InstallError(
            "Telefon test listesindeki eski sürüm işareti bulunamadı."
        )
    contents[CHECKLIST] = checklist.replace(
        "1.47.1+63",
        "1.48.2+66",
    )
    return contents


def validate_patched(
    contents: dict[Path, str],
    assets: dict[Path, bytes],
) -> None:
    markers: dict[Path, list[str]] = {
        MAIN: [
            "name: 'Kara Kedi'",
            "assets/pawns/17_kara_kedi.png",
            "_buildPremiumSpecialPawn",
            "if (type >= 12)",
        ],
        PICKER: [
            "Gece kristallerinin ışığında",
            "'GECE'",
            "Color(0xFF14B8A6)",
            "value <= 16",
        ],
        SOUNDS: [
            "profileCount = 17",
            "Kara Kedi Gece Kristali Tınısı",
            "[142, 920, 1840, .035, .20, 3, 5]",
        ],
        FX: [
            "Gece kristali pati izleri",
            "Taş tozu ve kristal ışığı",
        ],
        BUILD_INFO: [
            "versionName = '1.48.2'",
            "buildNumber = 66",
        ],
        PUBSPEC: ["version: 1.48.2+66"],
        SYSTEM_TEST: [
            "Piyon kataloğu beş özel karakter içerir",
            "contains('Kara Kedi')",
            "profileCount, 17",
            "normalize(-1), 16",
        ],
        RC_TEST: [
            "AppBuildInfo.versionName, '1.48.2'",
            "AppBuildInfo.buildNumber, 66",
            "PawnCatalog.all.length, 17",
        ],
        QUALITY: ['EXPECTED_VERSION = "1.48.2+66"'],
        WORKFLOW: [
            "BilgiRotasi-1.48.2-66-signed.apk",
            "BilgiRotasi-1.48.2-66-signed.aab",
            "BilgiRotasi-Signed-RC2-1.48.2-66",
        ],
        CHECKLIST: ["1.48.2+66 • RC2"],
    }
    for path, expected in markers.items():
        for marker in expected:
            if marker not in contents[path]:
                raise InstallError(
                    f"Kurulum doğrulaması başarısız: {path} / {marker}"
                )
    if len(assets) != 5:
        raise InstallError("Beş piyon görseli hazırlanamadı.")


def main() -> int:
    repo = locate_repo()

    branch = run(
        ["git", "branch", "--show-current"],
        cwd=repo,
    ).stdout.strip()
    if branch != "main":
        raise InstallError(
            f"Kurulum main dalında çalışmalıdır. "
            f"Mevcut dal: {branch or '(yok)'}"
        )

    required = [*TEXT_TARGETS, QUESTIONS]
    missing = [
        str(path) for path in required
        if not (repo / path).is_file()
    ]
    if missing:
        raise InstallError(
            "Gerekli proje dosyaları bulunamadı:\n"
            + "\n".join(missing)
        )

    protected = [*INTENDED_TARGETS, QUESTIONS]
    protected_status = run(
        [
            "git",
            "status",
            "--porcelain",
            "--",
            *[str(path) for path in protected],
        ],
        cwd=repo,
    ).stdout.strip()
    if protected_status:
        raise InstallError(
            "Kurulumun değiştireceği dosyalarda yerel değişiklik var:\n"
            + protected_status
            + "\nÖnce bu değişiklikleri commit et."
        )

    run(["git", "fetch", "origin", "main"], cwd=repo)
    divergence = run(
        [
            "git",
            "rev-list",
            "--left-right",
            "--count",
            "HEAD...origin/main",
        ],
        cwd=repo,
    ).stdout.strip().split()
    if len(divergence) != 2:
        raise InstallError("Git dal durumu okunamadı.")
    ahead, behind = map(int, divergence)
    if ahead > 0:
        raise InstallError(
            "GitHub'a gönderilmemiş yerel commit var. "
            "Önce git push origin main çalıştır."
        )
    if behind > 0:
        run(
            ["git", "pull", "--ff-only", "origin", "main"],
            cwd=repo,
            capture=False,
        )

    protected_status = run(
        [
            "git",
            "status",
            "--porcelain",
            "--",
            *[str(path) for path in protected],
        ],
        cwd=repo,
    ).stdout.strip()
    if protected_status:
        raise InstallError(
            "Güncellemeden sonra hedef dosyalarda değişiklik görüldü:\n"
            + protected_status
        )

    unrelated = run(
        ["git", "status", "--porcelain"],
        cwd=repo,
    ).stdout.splitlines()
    visible_unrelated = [
        line for line in unrelated
        if not any(name in line for name in INSTALLER_NAMES)
    ]
    if visible_unrelated:
        print("ℹ️ İlgisiz yerel değişiklikler korunacak:")
        for line in visible_unrelated:
            print("   " + line)

    question_hash_before = sha256(repo / QUESTIONS)
    contents = {
        path: (repo / path).read_text(encoding="utf-8")
        for path in TEXT_TARGETS
    }

    version_match = re.search(
        r"(?m)^version:\s*([^\s]+)\s*$",
        contents[PUBSPEC],
    )
    current_version = version_match.group(1) if version_match else "?"
    if current_version != BASE_VERSION:
        raise InstallError(
            f"Bu paket {BASE_VERSION} sürümü için hazırlandı. "
            f"Depodaki sürüm: {current_version}"
        )

    if "name: 'Kara Kedi'" in contents[MAIN]:
        raise InstallError(
            "Kara Kedi zaten piyon kataloğunda bulunuyor."
        )

    decoded_assets = verify_asset_payloads()

    # Bütün metin işaretlerini dosyalara yazmadan önce kontrol et.
    contents[MAIN] = patch_main(contents[MAIN])
    contents[PICKER] = patch_picker(contents[PICKER])
    contents[SOUNDS] = patch_sounds(contents[SOUNDS])
    contents[FX] = patch_fx(contents[FX])
    contents[SYSTEM_TEST] = patch_system_test(contents[SYSTEM_TEST])
    contents = patch_versions(contents)
    validate_patched(contents, decoded_assets)

    backup = Path(
        tempfile.mkdtemp(prefix="bilgi_rotasi_5_piyon_")
    )
    existed = backup_targets(repo, backup)
    committed = False

    try:
        for path, text in contents.items():
            destination = repo / path
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(
                text,
                encoding="utf-8",
                newline="\n",
            )

        for path, data in decoded_assets.items():
            destination = repo / path
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(data)

        if sha256(repo / QUESTIONS) != question_hash_before:
            raise InstallError(
                "Güvenlik kontrolü: assets/questions.json değişti."
            )

        dart_files = [
            str(MAIN),
            str(PICKER),
            str(SOUNDS),
            str(FX),
            str(BUILD_INFO),
            str(SYSTEM_TEST),
            str(RC_TEST),
        ]
        if shutil.which("dart"):
            run(
                ["dart", "format", *dart_files],
                cwd=repo,
                capture=False,
            )

        run(
            [
                "git",
                "diff",
                "--check",
                "--",
                *[str(path) for path in INTENDED_TARGETS],
            ],
            cwd=repo,
        )

        if shutil.which("python3"):
            report = (
                repo / ".git" / "RC2_PAWN_QUALITY_REPORT.md"
            )
            try:
                run(
                    [
                        "python3",
                        str(QUALITY),
                        "--report",
                        str(report),
                    ],
                    cwd=repo,
                    capture=False,
                )
            finally:
                report.unlink(missing_ok=True)

        if shutil.which("flutter"):
            run(
                [
                    "flutter",
                    "analyze",
                    "--no-fatal-warnings",
                    "--no-fatal-infos",
                ],
                cwd=repo,
                capture=False,
            )
            run(
                ["flutter", "test"],
                cwd=repo,
                capture=False,
            )
        else:
            print(
                "ℹ️ Flutter bu ortamda bulunamadı; "
                "analiz ve test GitHub Actions'ta çalışacak."
            )

        if sha256(repo / QUESTIONS) != question_hash_before:
            raise InstallError(
                "Testlerden sonra soru dosyası değişmiş görünüyor."
            )

        run(
            [
                "git",
                "add",
                "--",
                *[str(path) for path in INTENDED_TARGETS],
            ],
            cwd=repo,
        )

        staged = sorted(
            line.strip()
            for line in run(
                ["git", "diff", "--cached", "--name-only"],
                cwd=repo,
            ).stdout.splitlines()
            if line.strip()
        )
        expected = sorted(str(path) for path in INTENDED_TARGETS)
        if staged != expected:
            raise InstallError(
                "Commit dosyaları beklenenle eşleşmedi.\n"
                f"Beklenen: {expected}\n"
                f"Bulunan: {staged}"
            )

        if QUESTIONS.as_posix() in staged:
            raise InstallError(
                "Soru dosyası yanlışlıkla stage alanına girdi."
            )

        run(
            [
                "git",
                "commit",
                "-m",
                "Bes ozel piyonu yenile ve Kara Kedi ekle",
            ],
            cwd=repo,
            capture=False,
        )
        committed = True

        push_env = os.environ.copy()
        push_env.pop("GH_TOKEN", None)
        push_env.pop("GITHUB_TOKEN", None)
        run(
            ["git", "push", "origin", "main"],
            cwd=repo,
            capture=False,
            env=push_env,
        )

        print()
        print("✅ BEŞ ÖZEL PİYON KURULUMU TAMAMLANDI")
        print("✅ Minik Galaksi Bilgesi yenilendi.")
        print("✅ Fidan Muhafızı yenilendi.")
        print("✅ Özgür Ev Cini yenilendi.")
        print("✅ Mağara Sinsiği yenilendi.")
        print("✅ Kara Kedi yeni özel piyon olarak eklendi.")
        print("✅ Piyon seçimi, koleksiyon, tahta, ses ve efektler güncellendi.")
        print("✅ assets/questions.json dosyasına dokunulmadı.")
        print("✅ Yeni sürüm: 1.48.2+66 • RC2")
        print("✅ Değişiklikler GitHub main dalına gönderildi.")
        return 0

    except Exception:
        if not committed:
            restore_targets(repo, backup, existed)
            run(
                [
                    "git",
                    "restore",
                    "--staged",
                    "--",
                    *[str(path) for path in INTENDED_TARGETS],
                ],
                cwd=repo,
                check=False,
            )
        raise
    finally:
        shutil.rmtree(backup, ignore_errors=True)


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except InstallError as error:
        print()
        print("❌ KURULUM DURDU")
        print(str(error))
        raise SystemExit(1)
    except Exception as error:
        print()
        print("❌ KURULUM BAŞARISIZ")
        print(f"{type(error).__name__}: {error}")
        print(
            "Commit oluştuysa yalnızca şu komutu çalıştır: "
            "env -u GH_TOKEN -u GITHUB_TOKEN git push origin main"
        )
        raise SystemExit(1)
